//! Administrative read model only. No credentials or session token identifiers leave Rust.
use crate::{Store,StoreError,identity::{self,Permission}};use rusqlite::{params};use serde::{Serialize,Deserialize};use serde_json::{Value,json};
#[derive(Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct Query{pub employee_id:String,pub start_date:String,pub end_date:String,pub cursor:Option<String>,#[serde(default)]pub include_session_handles:bool,pub limit:i64}
impl Store{pub(crate) fn staff_access(&self,r:Query)->Result<Value,StoreError>{
 let tx=self.0.unchecked_transaction()?;let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&tx,s,Permission::Staff)?;
 if !crate::billing::valid_id(&r.employee_id)||!(1..=50).contains(&r.limit){return Err(StoreError::InvalidDraft);}crate::kitchen_history::validate_dates(&tx,&r.start_date,&r.end_date)?;
 if !tx.query_row("SELECT EXISTS(SELECT 1 FROM local_principals WHERE id=?1 AND business_id=?2)",params![r.employee_id,s.scope.business_id],|q|q.get::<_,bool>(0))?{return Err(StoreError::WorkspaceMismatch);}
 let (before,id)=if let Some(cursor)=r.cursor{if cursor.len()>512{return Err(StoreError::InvalidDraft);}let pair:(String,String)=serde_json::from_str(&cursor).map_err(|_|StoreError::InvalidDraft)?;if pair.0.len()>40||pair.1.len()>128{return Err(StoreError::InvalidDraft);}pair}else{(String::new(),String::new())};
 let mut events=tx.prepare(include_str!("staff_access-history.sql"))?.query_map(params![r.employee_id,s.scope.business_id,r.start_date,r.end_date,before,id,r.limit+1],|q|Ok(json!({"id":q.get::<_,String>(0)?,"actorId":q.get::<_,String>(1)?,"actorName":q.get::<_,String>(2)?,"responsibility":q.get::<_,String>(3)?,"revision":q.get::<_,i64>(4)?,"createdAt":q.get::<_,String>(5)?})))?.collect::<Result<Vec<_>,_>>()?;
 let more=events.len()>r.limit as usize;events.truncate(r.limit as usize);let cursor=if more{events.last().map(|v|serde_json::to_string(&(v["createdAt"].as_str().unwrap_or(""),v["id"].as_str().unwrap_or("")))).transpose()?}else{None};
 let employee_revision:i64=tx.query_row("SELECT revision FROM local_principals WHERE id=?1 AND business_id=?2",params![r.employee_id,s.scope.business_id],|q|q.get(0))?;
 let sessions=tx.prepare(include_str!("staff_access-sessions.sql"))?.query_map(params![r.employee_id,s.scope.business_id],|q|{let mut value=json!({"deviceId":q.get::<_,String>(0)?,"name":q.get::<_,String>(1)?,"expires":q.get::<_,i64>(2)?,"lastSeen":q.get::<_,Option<i64>>(3)?});if r.include_session_handles{if let Some(handle)=q.get::<_,Option<String>>(4)?{value["sessionHandle"]=json!(handle);}}Ok(value)})?.collect::<Result<Vec<_>,_>>()?;
 let generated:String=tx.query_row("SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now')",[],|q|q.get(0))?;let mut result=json!({"employeeId":r.employee_id,"generatedAt":generated,"events":events,"nextCursor":cursor,"sessions":sessions});if r.include_session_handles{result["employeeRevision"]=json!(employee_revision);}tx.commit()?;Ok(result)
}}
#[cfg(test)]mod tests{use super::*;use crate::{access::Workspace,kitchen::Action,identity::{Role,StaffDetails}};const PASSWORD:&str="Synthetic staff access password";const KEY:&str="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
fn query(employee:String)->Query{Query{employee_id:employee,start_date:String::new(),end_date:String::new(),cursor:None,include_session_handles:false,limit:25}}
#[test]fn staff_reports_require_administration_even_for_valid_kitchen_accounts(){let mut w=Workspace::new(Store::open(std::path::Path::new(":memory:"),KEY).unwrap());w.setup(PASSWORD).unwrap();let owner=w.local_session().unwrap().principal.id;let report=w.kitchen_action(Action::StaffAccess{query:query(owner.clone())}).unwrap();assert!(report["sessions"].as_array().unwrap().is_empty());let cook=w.create_staff(StaffDetails{username:"cook".into(),display_name:"Cook".into(),role:Role::Cashier},PASSWORD).unwrap();w.lock();w.login("cook",PASSWORD).unwrap();assert!(w.kitchen_action(Action::StaffAccess{query:query(owner)}).is_err());assert!(w.kitchen_action(Action::StaffAccess{query:query(cook.id)}).is_err());}
#[test]fn bounded_queries_refuse_missing_targets_and_invalid_dates(){let mut w=Workspace::new(Store::open(std::path::Path::new(":memory:"),KEY).unwrap());w.setup(PASSWORD).unwrap();assert!(w.kitchen_action(Action::StaffAccess{query:query("foreign".into())}).is_err());let owner=w.local_session().unwrap().principal.id;let mut invalid=query(owner.clone());invalid.limit=51;assert!(w.kitchen_action(Action::StaffAccess{query:invalid}).is_err());let mut invalid=query(owner);invalid.start_date="2026-02-30".into();assert!(w.kitchen_action(Action::StaffAccess{query:invalid}).is_err());}
}
